public sealed class CustomerInputValidator:AbstractValidator<CustomerInput>{public CustomerInputValidator(){RuleFor(x=>x.CustomerCode).NotEmpty().MaximumLength(50);RuleFor(x=>x.CustomerName).NotEmpty().MaximumLength(250);RuleFor(x=>x.CustomerType).NotEmpty();RuleFor(x=>x.GSTIN).Matches("^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$").When(x=>!string.IsNullOrWhiteSpace(x.GSTIN));RuleFor(x=>x.PAN).Matches("^[A-Z]{5}[0-9]{4}[A-Z]$").When(x=>!string.IsNullOrWhiteSpace(x.PAN));RuleFor(x=>x.Email).EmailAddress().When(x=>!string.IsNullOrWhiteSpace(x.Email));RuleFor(x=>x.Mobile).Matches("^[6-9][0-9]{9}$").When(x=>!string.IsNullOrWhiteSpace(x.Mobile));RuleFor(x=>x.CreditLimit).GreaterThanOrEqualTo(0);}}public sealed class CreateValidator:AbstractValidator<CreateCustomer>{public CreateValidator()=>RuleFor(x=>x.Input).SetValidator(new CustomerInputValidator());}public sealed class UpdateValidator:AbstractValidator<UpdateCustomer>{public UpdateValidator()=>RuleFor(x=>x.Input).SetValidator(new CustomerInputValidator());}
internal static class Map{public static CustomerDto D(Customer c)=>new(c.CustomerId,c.CustomerCode,c.CustomerName,c.CustomerType,c.GSTIN,c.PAN,c.Email,c.Mobile,c.Telephone,c.Website,c.Currency,c.PaymentTermId,c.PaymentTerm?.PaymentTermName,c.CreditLimit,c.OpeningBalance,c.SalesPersonId,c.CustomerGroupId,c.PriceListId,c.IsGSTRegistered,c.IsActive,c.Remarks,c.Contacts.Select(x=>new ContactDto(x.ContactId,x.ContactPerson,x.Designation,x.Department,x.Mobile,x.Email,x.IsPrimary)).ToArray(),c.Addresses.Select(x=>new AddressDto(x.AddressId,x.AddressType,x.AddressLine1,x.AddressLine2,x.City,x.District,x.State,x.Country,x.PostalCode)).ToArray(),c.BankAccounts.Select(x=>new BankDto(x.BankAccountId,x.BankName,x.Branch,x.AccountNumber,x.IFSCCode,x.UPIId)).ToArray(),c.Documents.Where(x=>!x.IsDeleted).Select(x=>new CustomerDocumentDto(x.DocumentId,x.DocumentType,x.FileName,x.ContentType,x.UploadedOn)).ToArray());public static void Apply(Customer c,CustomerInput i){c.CustomerCode=i.CustomerCode.Trim();c.CustomerName=i.CustomerName.Trim();c.CustomerType=i.CustomerType;c.GSTIN=i.GSTIN?.ToUpperInvariant();c.PAN=i.PAN?.ToUpperInvariant();c.Email=i.Email;c.Mobile=i.Mobile;c.Telephone=i.Telephone;c.Website=i.Website;c.Currency=i.Currency.ToUpperInvariant();c.PaymentTermId=i.PaymentTermId;c.CreditLimit=i.CreditLimit;c.OpeningBalance=i.OpeningBalance;c.SalesPersonId=i.SalesPersonId;c.CustomerGroupId=i.CustomerGroupId;c.PriceListId=i.PriceListId;c.IsGSTRegistered=i.IsGSTRegistered;c.IsActive=i.IsActive;c.Remarks=i.Remarks;c.Contacts=i.Contacts.Select(x=>new CustomerContact{ContactPerson=x.ContactPerson,Designation=x.Designation,Department=x.Department,Mobile=x.Mobile,Email=x.Email,IsPrimary=x.IsPrimary}).ToList();c.Addresses=i.Addresses.Select(x=>new CustomerAddress{AddressType=x.AddressType,AddressLine1=x.AddressLine1,AddressLine2=x.AddressLine2,City=x.City,District=x.District,State=x.State,Country=x.Country,PostalCode=x.PostalCode}).ToList();c.BankAccounts=i.BankAccounts.Select(x=>new CustomerBankAccount{BankName=x.BankName,Branch=x.Branch,AccountNumber=x.AccountNumber,IFSCCode=x.IFSCCode,UPIId=x.UPIId}).ToList();}}
public sealed class Handlers(ICustomerRepository r,ICustomerSpreadsheetService excel,ICurrentUserService user):IRequestHandler<GetCustomers,PagedCustomers>,IRequestHandler<GetCustomer,CustomerDto>,IRequestHandler<CreateCustomer,CustomerDto>,IRequestHandler<UpdateCustomer,CustomerDto>,IRequestHandler<DeleteCustomer>,IRequestHandler<Dropdown,IReadOnlyCollection<CustomerDropdownDto>>,IRequestHandler<Terms,IReadOnlyCollection<TermDto>>,IRequestHandler<ExportCustomers,byte[]>,IRequestHandler<Template,byte[]>,IRequestHandler<ImportCustomers,ImportResult>,IRequestHandler<UploadDocument,CustomerDocumentDto>,IRequestHandler<GetDocument,DocumentFile?>,IRequestHandler<DeleteDocument>{public async Task<PagedCustomers> Handle(GetCustomers q,CancellationToken t){var(x,n)=await r.Search(q.Search,q.IsActive,q.Sort,q.Desc,q.Page,q.Size,t);return new(x.Select(c=>new CustomerListDto(c.CustomerId,c.CustomerCode,c.CustomerName,c.CustomerType,c.GSTIN,c.Mobile,c.Email,c.Currency,c.CreditLimit,c.IsActive)).ToArray(),n,q.Page,q.Size);}public async Task<CustomerDto> Handle(GetCustomer q,CancellationToken t)=>Map.D(await r.GetById(q.Id,false,t)??throw new EntityNotFoundException("Customer not found."));public async Task<CustomerDto> Handle(CreateCustomer q,CancellationToken t){if(await r.Duplicate(q.Input.CustomerCode,q.Input.GSTIN,q.Input.CustomerName,null,t))throw new BusinessRuleException("Duplicate customer.");var c=new Customer{CreatedBy=user.Username};Map.Apply(c,q.Input);r.Add(c);await r.Save(t);return Map.D(await r.GetById(c.CustomerId,false,t)??c);}public async Task<CustomerDto> Handle(UpdateCustomer q,CancellationToken t){var c=await r.GetById(q.Id,true,t)??throw new EntityNotFoundException("Customer not found.");if(await r.Duplicate(q.Input.CustomerCode,q.Input.GSTIN,q.Input.CustomerName,q.Id,t))throw new BusinessRuleException("Duplicate customer.");r.RemoveChildren(c);Map.Apply(c,q.Input);c.ModifiedOn=DateTimeOffset.UtcNow;c.ModifiedBy=user.Username;await r.Save(t);return Map.D(await r.GetById(c.CustomerId,false,t)??c);}public async Task Handle(DeleteCustomer q,CancellationToken t){var c=await r.GetById(q.Id,true,t)??throw new EntityNotFoundException("Customer not found.");c.IsDeleted=true;c.IsActive=false;await r.Save(t);}public async Task<IReadOnlyCollection<CustomerDropdownDto>> Handle(Dropdown q,CancellationToken t){var(x,_)=await r.Search(q.Search,true,"customerName",false,1,100,t);return x.Select(c=>new CustomerDropdownDto(c.CustomerId,c.CustomerCode,c.CustomerName)).ToArray();}public async Task<IReadOnlyCollection<TermDto>> Handle(Terms q,CancellationToken t)=>(await r.Terms(t)).Select(x=>new TermDto(x.PaymentTermId,x.PaymentTermName,x.DueDays,x.IsDefault)).ToArray();public async Task<byte[]> Handle(ExportCustomers q,CancellationToken t){var(x,_)=await r.Search(null,null,"customerName",false,1,10000,t);return excel.Export(x);}public Task<byte[]> Handle(Template q,CancellationToken t)=>Task.FromResult(excel.Template());public async Task<ImportResult> Handle(ImportCustomers q,CancellationToken t){var e=new List<string>();var n=0;foreach(var x in excel.Read(q.Data)){if(await r.Duplicate(x.Code,x.GSTIN,x.Name,null,t)){e.Add($"Row {x.Row}: duplicate customer.");continue;}r.Add(new Customer{CustomerCode=x.Code,CustomerName=x.Name,CustomerType=x.Type,GSTIN=x.GSTIN,PAN=x.PAN,Email=x.Email,Mobile=x.Mobile,Currency=x.Currency,CreditLimit=x.CreditLimit,IsActive=x.Active,CreatedBy=user.Username});n++;}if(n>0)await r.Save(t);return new(n,e);}public async Task<CustomerDocumentDto> Handle(UploadDocument q,CancellationToken t){_=await r.GetById(q.CustomerId,false,t)??throw new EntityNotFoundException("Customer not found.");var d=new CustomerDocument{CustomerId=q.CustomerId,DocumentType=q.Type,FileName=q.Name,ContentType=q.ContentType,DocumentData=q.Data,UploadedBy=user.Username};r.Add(d);await r.Save(t);return new(d.DocumentId,d.DocumentType,d.FileName,d.ContentType,d.UploadedOn);}public async Task<DocumentFile?> Handle(GetDocument q,CancellationToken t){var d=await r.Document(q.CustomerId,q.DocumentId,false,t);return d is null?null:new(d.FileName,d.ContentType,d.DocumentData);}public async Task Handle(DeleteDocument q,CancellationToken t){var d=await r.Document(q.CustomerId,q.DocumentId,true,t)??throw new EntityNotFoundException("Document not found.");d.IsDeleted=true;await r.Save(t);}}
